export default JSON.parse(
  "{\n  \"workId\": \"xunzi\",\n  \"chapter\": {\n    \"id\": \"xunzi_ch-9\",\n    \"workId\": \"xunzi\",\n    \"order\": 9,\n    \"title\": \"王制\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 17,\n    \"passageIds\": [\n      \"xunzi_ch-9_p-1\",\n      \"xunzi_ch-9_p-2\",\n      \"xunzi_ch-9_p-3\",\n      \"xunzi_ch-9_p-4\",\n      \"xunzi_ch-9_p-5\",\n      \"xunzi_ch-9_p-6\",\n      \"xunzi_ch-9_p-7\",\n      \"xunzi_ch-9_p-8\",\n      \"xunzi_ch-9_p-9\",\n      \"xunzi_ch-9_p-10\",\n      \"xunzi_ch-9_p-11\",\n      \"xunzi_ch-9_p-12\",\n      \"xunzi_ch-9_p-13\",\n      \"xunzi_ch-9_p-14\",\n      \"xunzi_ch-9_p-15\",\n      \"xunzi_ch-9_p-16\",\n      \"xunzi_ch-9_p-17\",\n      \"xunzi_ch-9_p-18\",\n      \"xunzi_ch-9_p-19\",\n      \"xunzi_ch-9_p-20\",\n      \"xunzi_ch-9_p-21\",\n      \"xunzi_ch-9_p-22\",\n      \"xunzi_ch-9_p-23\",\n      \"xunzi_ch-9_p-24\",\n      \"xunzi_ch-9_p-25\",\n      \"xunzi_ch-9_p-26\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"性惡論\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"xunzi_ch-9_p-1\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 1,\n      \"canonicalText\": \"請問為政？曰：賢能不待次而舉，罷不能不待須而廢，元惡不待教而誅，中庸雜民不待政而化。分未定也，則有昭繆也。雖王公士大夫之子孫也，不能屬於禮義，則歸之庶人。雖庶人之子孫也，積文學，正身行，能屬於禮義，則歸之卿相士大夫。故姦言，姦說，姦事，姦能，遁逃反側之民，職而教之，須而待之，勉之以慶賞，懲之以刑罰。安職則畜，不安職則棄。五疾，上收而養之，材而事之，官施而衣食之，兼覆無遺。纔行反時者死無赦。夫是之謂天德，是王者之政也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-1_s-1\",\n        \"xunzi_ch-9_p-1_s-2\",\n        \"xunzi_ch-9_p-1_s-3\",\n        \"xunzi_ch-9_p-1_s-4\",\n        \"xunzi_ch-9_p-1_s-5\",\n        \"xunzi_ch-9_p-1_s-6\",\n        \"xunzi_ch-9_p-1_s-7\",\n        \"xunzi_ch-9_p-1_s-8\",\n        \"xunzi_ch-9_p-1_s-9\",\n        \"xunzi_ch-9_p-1_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"請問為政？說道：賢能不待次而且舉，罷不能不待須而且廢，元惡不待教而且誅，中庸雜民不待政而且化。分未定啊，則有昭繆啊。雖王公士大夫的子孫啊，不能屬於禮道義正道道德行修養規程道義正道，則歸的庶人。雖庶人的子孫啊，積文學，正身行，能屬於禮道義正道道德行修養規程道義正道，則歸的卿相士大夫。所以姦言，姦說，姦事，姦能，遁逃反側的民，職而且教的，須而且待的，勉的以慶賞，懲的以刑罰。安職則畜，不安職則棄。五疾，上收而且養的，材而且事的，官施而且衣食的，兼覆無遺。纔行反時的人或事死無赦。這就是儒家所說的天德行修養，是王的人或事的政啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「請問為政」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「請」、「問」、「為」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「請問為政曰賢能不待次而舉罷不能不待須而廢元惡不待」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「曰：賢能不待次而舉，罷不能不待須而廢，元惡不待教而誅，中庸雜民不待政而化」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-2\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 2,\n      \"canonicalText\": \"聽政之大分：以善至者待之以禮，以不善至者待之以刑。兩者分別，則賢不肖不雜，是非不亂。賢不肖不雜，則英傑至，是非不亂，則國家治。若是，名聲日聞，天下願，令行禁止，王者之事畢矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-2_s-1\",\n        \"xunzi_ch-9_p-2_s-2\",\n        \"xunzi_ch-9_p-2_s-3\",\n        \"xunzi_ch-9_p-2_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"聽政的大分：以善至的人或事待的以禮道義正道道德行修養規程，以不善至的人或事待的以刑。兩的人或事分別，則賢不肖不雜，是絕不是不亂。賢不肖不雜，則英傑至，是絕不是不亂，則國家治。若是，名聲日聞，天下願，令行禁止，王的人或事的事畢矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「聽政之大分：以善至者待之以禮，以不善至者待之以刑」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「聽」、「政」、「大」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「聽政之大分以善至者待之以禮以不善至者待之以刑兩者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「兩者分別，則賢不肖不雜，是非不亂」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 3,\n      \"canonicalText\": \"凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭。若是，則大事殆乎弛，小事殆乎遂。和解調通，好假道人，而無所凝止之，則姦言並至，嘗試之說鋒起。若是，則聽大事煩，是又傷之也。故法而不議，則法之所不至者必廢。職而不通，則職之所不及者必隊。故法而議，職而通，無隱謀，無遺善，而百事無過，非君子莫能。故公平者，聽之衡也；中和者，聽之繩也。其有法者以法行，無法者以類舉，聽之盡也。偏黨而不經，聽之闢也。故有良法而亂者，有之矣，有君子而亂者，自古及今，未嘗聞也。傳曰：「治生乎君子，亂生乎小人。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-3_s-1\",\n        \"xunzi_ch-9_p-3_s-2\",\n        \"xunzi_ch-9_p-3_s-3\",\n        \"xunzi_ch-9_p-3_s-4\",\n        \"xunzi_ch-9_p-3_s-5\",\n        \"xunzi_ch-9_p-3_s-6\",\n        \"xunzi_ch-9_p-3_s-7\",\n        \"xunzi_ch-9_p-3_s-8\",\n        \"xunzi_ch-9_p-3_s-9\",\n        \"xunzi_ch-9_p-3_s-10\",\n        \"xunzi_ch-9_p-3_s-11\",\n        \"xunzi_ch-9_p-3_s-12\",\n        \"xunzi_ch-9_p-3_s-13\",\n        \"xunzi_ch-9_p-3_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡聽：威嚴猛厲，而且不好假道人，則下畏恐而且不親，周閉而且不竭。若是，則大事殆乎弛，小事殆乎遂。和解調通，好假道人，而且無所凝止的，則姦言並至，嘗試的說鋒起。若是，則聽大事煩，是又傷的啊。所以典章法度而且不議，則典章法度的所不至的人或事必廢。職而且不通，則職的所不及的人或事必隊。所以典章法度而且議，職而且通，無隱謀，無遺善，而且百事無過，絕不是君子莫能。所以公平的人或事，聽1的衡啊；中和的人或事，聽的繩啊。他的有典章法度的人或事以典章法度行，無典章法度的人或事以類舉，聽的盡啊。偏黨而且不經，聽的闢啊。所以有良典章法度而且亂的人或事，有的矣，有君子而且亂的人或事，自古及今，未嘗聞啊。傳說道：治生乎君子，亂生乎小人。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「聽」、「威」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「凡聽威嚴猛厲而不好假道人則下畏恐而不親周閉而不竭」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「若是，則大事殆乎弛，小事殆乎遂」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 4,\n      \"canonicalText\": \"分均則不偏，埶齊則不壹，眾齊則不使。有天有地，而上下有差；明王始立，而處國有制。夫兩貴之不能相事，兩賤之不能相使，是天數也。埶位齊，而欲惡同，物不能澹則必爭；爭則必亂，亂則窮矣。先王惡其亂也，故制禮義以分之，使有貧富貴賤之等，足以相兼臨者，是養天下之本也。《書》曰：「維齊非齊。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-4_s-1\",\n        \"xunzi_ch-9_p-4_s-2\",\n        \"xunzi_ch-9_p-4_s-3\",\n        \"xunzi_ch-9_p-4_s-4\",\n        \"xunzi_ch-9_p-4_s-5\",\n        \"xunzi_ch-9_p-4_s-6\",\n        \"xunzi_ch-9_p-4_s-7\",\n        \"xunzi_ch-9_p-4_s-8\",\n        \"xunzi_ch-9_p-4_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"分均則不偏，埶齊則不壹，眾齊則不使。有天有地，而且上下有差；明王始立，而且處國有制。夫兩貴的不能相事，兩賤的不能相使，是天數啊。埶位齊，而且欲惡同，物不能澹則必爭；爭則必亂，亂則窮矣。先王惡他的亂啊，所以制禮道義正道道德行修養規程道義正道以分的，使有貧富貴賤的等，足以相兼臨的人或事，是養天下的本啊。《書》說道：維齊絕不是齊。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「分均則不偏，埶齊則不壹，眾齊則不使」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「分」、「均」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「分均則不偏埶齊則不壹眾齊則不使有天有地而上下有差」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「有天有地，而上下有差」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 5,\n      \"canonicalText\": \"馬駭輿，則君子不安輿；庶人駭政，則君子不安位。馬駭輿，則莫若靜之；庶人駭政，則莫若惠之。選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。如是，則庶人安政矣。庶人安政，然後君子安位。傳曰：「君者、舟也，庶人者、水也；水則載舟，水則覆舟。」此之謂也。故君人者，欲安、則莫若平政愛民矣；欲榮、則莫若隆禮敬士矣；欲立功名、則莫若尚賢使能矣。－是人君之大節也。三節者當，則其餘莫不當矣。三節者不當，則其餘雖曲當，猶將無益也。孔子曰：「大節是也，小節是也，上君也；大節是也，小節一齣焉，一入焉，中君也；大節非也，小節雖是也，吾無觀其餘矣。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-5_s-1\",\n        \"xunzi_ch-9_p-5_s-2\",\n        \"xunzi_ch-9_p-5_s-3\",\n        \"xunzi_ch-9_p-5_s-4\",\n        \"xunzi_ch-9_p-5_s-5\",\n        \"xunzi_ch-9_p-5_s-6\",\n        \"xunzi_ch-9_p-5_s-7\",\n        \"xunzi_ch-9_p-5_s-8\",\n        \"xunzi_ch-9_p-5_s-9\",\n        \"xunzi_ch-9_p-5_s-10\",\n        \"xunzi_ch-9_p-5_s-11\",\n        \"xunzi_ch-9_p-5_s-12\",\n        \"xunzi_ch-9_p-5_s-13\",\n        \"xunzi_ch-9_p-5_s-14\",\n        \"xunzi_ch-9_p-5_s-15\",\n        \"xunzi_ch-9_p-5_s-16\",\n        \"xunzi_ch-9_p-5_s-17\",\n        \"xunzi_ch-9_p-5_s-18\",\n        \"xunzi_ch-9_p-5_s-19\",\n        \"xunzi_ch-9_p-5_s-20\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"馬駭輿，則君子不安輿；庶人駭政，則君子不安位。馬駭輿，則莫若靜的；庶人駭政，則莫若惠的。選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。如是，則庶人安政矣。庶人安政，然後君子安位。傳說道：君的人或事、舟啊，庶人的人或事、水啊；水則載舟，水則覆舟。此的謂啊。所以君人的人或事，欲安、則莫若平政愛民矣；欲榮、則莫若隆禮道義正道道德行修養規程敬士矣；欲立功名、則莫若尚賢使能矣。－是人君的大節啊。三節的人或事當，則他的餘莫不當矣。三節的人或事不當，則他的餘雖曲當，猶將無益啊。孔子說道：大節是啊，小節是啊，上君啊；大節是啊，小節一齣焉，一入焉，中君啊；大節絕不是啊，小節雖是啊，吾無觀他的餘矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「馬駭輿，則君子不安輿」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「馬」、「駭」、「輿」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「馬駭輿則君子不安輿庶人駭政則君子不安位馬駭輿則莫」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「庶人駭政，則君子不安位」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 6,\n      \"canonicalText\": \"成侯、嗣公聚斂計數之君也，未及取民也。子產取民者也，未及為政也。管仲為政者也，未及修禮也。故修禮者王，為政者彊，取民者安，聚斂者亡。故王者富民，霸者富士，僅存之國富大夫，亡國富筐篋，實府庫。筐篋已富，府庫已實，而百姓貧：夫是之謂上溢而下漏。入不可以守，出不可以戰，則傾覆滅亡可立而待也。故我聚之以亡，敵得之以彊。聚斂者，召寇、肥敵、亡國、危身之道也，故明君不蹈也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-6_s-1\",\n        \"xunzi_ch-9_p-6_s-2\",\n        \"xunzi_ch-9_p-6_s-3\",\n        \"xunzi_ch-9_p-6_s-4\",\n        \"xunzi_ch-9_p-6_s-5\",\n        \"xunzi_ch-9_p-6_s-6\",\n        \"xunzi_ch-9_p-6_s-7\",\n        \"xunzi_ch-9_p-6_s-8\",\n        \"xunzi_ch-9_p-6_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"成侯、嗣公聚斂計數的君啊，未及取民啊。子產取民的人或事啊，未及為政啊。管仲為政的人或事啊，未及修禮道義正道道德行修養規程啊。所以修禮道義正道道德行修養規程的人或事王，為政的人或事彊，取民的人或事安，聚斂的人或事亡。所以王的人或事富民，霸的人或事富士，僅存的國富大夫，亡國富筐篋，實府庫。筐篋已富，府庫已實，而且百姓貧：這就是儒家所說的上溢而且下漏。入不可以守，出不可以戰，則傾覆滅亡可立而且待啊。所以我聚的以亡，敵得的以彊。聚斂的人或事，召寇、肥敵、亡國、危身的道啊，所以明君不蹈啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「成侯、嗣公聚斂計數之君也，未及取民也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「成」、「侯」、「嗣」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「成侯嗣公聚斂計數之君也未及取民也子產取民者也未及」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「子產取民者也，未及為政也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-7\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 7,\n      \"canonicalText\": \"王奪之人，霸奪之與，彊奪之地。奪之人者臣諸侯，奪之與者友諸侯，奪之地者敵諸侯。臣諸侯者王，友諸侯者霸，敵諸侯者危。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-7_s-1\",\n        \"xunzi_ch-9_p-7_s-2\",\n        \"xunzi_ch-9_p-7_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王奪的人，霸奪的與，彊奪的地。奪的人的人或事臣諸侯，奪的與的人或事友諸侯，奪的地的人或事敵諸侯。臣諸侯的人或事王，友諸侯的人或事霸，敵諸侯的人或事危。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「王奪之人，霸奪之與，彊奪之地」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「奪」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「王奪之人霸奪之與彊奪之地奪之人者臣諸侯奪之與者友」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「奪之人者臣諸侯，奪之與者友諸侯，奪之地者敵諸侯」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 8,\n      \"canonicalText\": \"用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣；傷人之民甚，則人之民必惡我甚矣；人之民惡我甚，則日欲與我鬥。人之城守，人之出戰，而我以力勝之，則傷吾民必甚矣；傷吾民甚，則吾民之惡我必甚矣；吾民之惡我甚，則日不欲為我鬥。人之民日欲與我鬥，吾民日不欲為我鬥，是彊者之所以反弱也。地來而民去，累多而功少，雖守者益，所以守者損，是以大者之所以反削也。諸侯莫不懷交接怨，而不忘其敵，伺彊大之間，承彊大之敝，此彊大之殆時也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-8_s-1\",\n        \"xunzi_ch-9_p-8_s-2\",\n        \"xunzi_ch-9_p-8_s-3\",\n        \"xunzi_ch-9_p-8_s-4\",\n        \"xunzi_ch-9_p-8_s-5\",\n        \"xunzi_ch-9_p-8_s-6\",\n        \"xunzi_ch-9_p-8_s-7\",\n        \"xunzi_ch-9_p-8_s-8\",\n        \"xunzi_ch-9_p-8_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"用彊的人或事：人的城守，人的出戰，而且我以力勝的啊，則傷人的民必甚矣；傷人的民甚，則人的民必惡我甚矣；人的民惡我甚，則日欲與我鬥。人的城守，人的出戰，而且我以力勝的，則傷吾民必甚矣；傷吾民甚，則吾民的惡我必甚矣；吾民的惡我甚，則日不欲為我鬥。人的民日欲與我鬥，吾民日不欲為我鬥，是彊的人或事的所以反弱啊。地來而且民去，累多而且功少，雖守的人或事益，所以守的人或事損，是以大的人或事的所以反削啊。諸侯莫不懷交接怨，而且不忘他的敵，伺彊大的間，承彊大的敝，此彊大的殆時啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「用」、「彊」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「用彊者人之城守人之出戰而我以力勝之也則傷人之民必」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「傷人之民甚，則人之民必惡我甚矣」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-9\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 9,\n      \"canonicalText\": \"知彊大者不務彊也，慮以王命，全其力，凝其德。力全則諸侯不能弱也，德凝則諸侯不能削也，天下無王霸主，則常勝矣：是知彊道者也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-9_s-1\",\n        \"xunzi_ch-9_p-9_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"知彊大的人或事不務彊啊，慮以王命，全他的力，凝他的德行修養。力全則諸侯不能弱啊，德行修養凝則諸侯不能削啊，天下無王霸主，則常勝矣：是知彊道的人或事啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「知彊大者不務彊也，慮以王命，全其力，凝其德」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「知」、「彊」、「大」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「知彊大者不務彊也慮以王命全其力凝其德力全則諸侯不」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「力全則諸侯不能弱也，德凝則諸侯不能削也，天下無王霸主，則常勝矣：是知彊道者也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 10,\n      \"canonicalText\": \"彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之。存亡繼絕，衛弱禁暴，而無兼併之心，則諸侯親之矣。修友敵之道，以敬接諸侯，則諸侯說之矣。所以親之者，以不併也；並之見，則諸侯疏矣。所以說之者，以友敵也；臣之見，則諸侯離矣。故明其不併之行，信其友敵之道，天下無王霸主，則常勝矣。是知霸道者也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-10_s-1\",\n        \"xunzi_ch-9_p-10_s-2\",\n        \"xunzi_ch-9_p-10_s-3\",\n        \"xunzi_ch-9_p-10_s-4\",\n        \"xunzi_ch-9_p-10_s-5\",\n        \"xunzi_ch-9_p-10_s-6\",\n        \"xunzi_ch-9_p-10_s-7\",\n        \"xunzi_ch-9_p-10_s-8\",\n        \"xunzi_ch-9_p-10_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"彼霸的人或事則不然：闢田野，實倉廩，便備用，案謹募選閱材伎的士，然後漸慶賞以先的，嚴刑罰以糾的。存亡繼絕，衛弱禁暴，而且無兼併的心，則諸侯親的矣。修友敵的道，以敬接諸侯，則諸侯說的矣。所以親的的人或事，以不併啊；並的見，則諸侯疏矣。所以說的的人或事，以友敵啊；臣的見，則諸侯離矣。所以明他的不併的行，信他的友敵的道，天下無王霸主，則常勝矣。是知霸道的人或事啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「霸」、「不」、「然」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「彼霸者則不然闢田野實倉廩便備用案謹募選閱材伎之士」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「存亡繼絕，衛弱禁暴，而無兼併之心，則諸侯親之矣」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-11\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 11,\n      \"canonicalText\": \"閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-11_s-1\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"閔王毀於五國，桓公劫於魯莊，無它所以焉，絕不是他的道而且慮的以王啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「閔」、「王」、「毀」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「閔王毀於五國桓公劫於魯莊無它故焉非其道而慮之以王」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 12,\n      \"canonicalText\": \"彼王者不然：仁眇天下，義眇天下，威眇天下。仁眇天下，故天下莫不親也；義眇天下，故天下莫不貴也；威眇天下，故天下莫敢敵也。以不敵之威，輔服人之道，故不戰而勝，不攻而得，甲兵不勞而天下服，是知王道者也。知此三具者，欲王而王，欲霸而霸，欲彊而彊矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-12_s-1\",\n        \"xunzi_ch-9_p-12_s-2\",\n        \"xunzi_ch-9_p-12_s-3\",\n        \"xunzi_ch-9_p-12_s-4\",\n        \"xunzi_ch-9_p-12_s-5\",\n        \"xunzi_ch-9_p-12_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"彼王的人或事不然：仁愛之德眇天下，道義正道眇天下，威眇天下。仁愛之德眇天下，所以天下莫不親啊；道義正道眇天下，所以天下莫不貴啊；威眇天下，所以天下莫敢敵啊。以不敵的威，輔服人的道，所以不戰而且勝，不攻而且得，甲兵不勞而且天下服，是知王道的人或事啊。知此三具的人或事，欲王而且王，欲霸而且霸，欲彊而且彊矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「彼王者不然：仁眇天下，義眇天下，威眇天下」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「不」、「然」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「彼王者不然仁眇天下義眇天下威眇天下仁眇天下故天下」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「仁眇天下，故天下莫不親也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-13\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 13,\n      \"canonicalText\": \"王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原。是王者之人也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-13_s-1\",\n        \"xunzi_ch-9_p-13_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王的人或事的人：飾動以禮道義正道道德行修養規程道義正道，聽斷以類，明振毫末，舉措應變而且不窮，這就是儒家所說的有原。是王的人或事的人啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「人」、「飾」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「王者之人飾動以禮義聽斷以類明振毫末舉措應變而不窮」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「是王者之人也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-14\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 14,\n      \"canonicalText\": \"王者之制：道不過三代，法不二後王；道過三代謂之蕩，法二後王謂之不雅。衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。聲、則非雅聲者舉廢，色、則凡非舊文者舉息，械用，則凡非舊器者舉毀，夫是之謂復古，是王者之制也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-14_s-1\",\n        \"xunzi_ch-9_p-14_s-2\",\n        \"xunzi_ch-9_p-14_s-3\",\n        \"xunzi_ch-9_p-14_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王的人或事的制：道不過三代，典章法度不二後王；道過三代謂的蕩，典章法度二後王謂的不雅。衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。聲、則絕不是雅聲的人或事舉廢，色、則凡絕不是舊文的人或事舉息，械用，則凡絕不是舊器的人或事舉毀，這就是儒家所說的復古，是王的人或事的制啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「王者之制：道不過三代，法不二後王」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「制」、「道」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「王者之制道不過三代法不二後王道過三代謂之蕩法二後」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「道過三代謂之蕩，法二後王謂之不雅」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 15,\n      \"canonicalText\": \"王者之論：無德不貴，無能不官，無功不賞，無罪不罰。朝無幸位，民無幸生。尚賢使能，而等位不遺；析願禁悍，而刑罰不過。百姓曉然皆知夫為善於家，而取賞於朝也；為不善於幽，而蒙刑於顯也。夫是之謂定論。是王者之論也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-15_s-1\",\n        \"xunzi_ch-9_p-15_s-2\",\n        \"xunzi_ch-9_p-15_s-3\",\n        \"xunzi_ch-9_p-15_s-4\",\n        \"xunzi_ch-9_p-15_s-5\",\n        \"xunzi_ch-9_p-15_s-6\",\n        \"xunzi_ch-9_p-15_s-7\",\n        \"xunzi_ch-9_p-15_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王的人或事的論：無德行修養不貴，無能不官，無功不賞，無罪不罰。朝無幸位，民無幸生。尚賢使能，而且等位不遺；析願禁悍，而且刑罰不過。百姓曉然皆知夫為善於家，而且取賞於朝啊；為不善於幽，而且蒙刑於顯啊。這就是儒家所說的定論。是王的人或事的論啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「王者之論：無德不貴，無能不官，無功不賞，無罪不罰」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「論」、「無」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「王者之論無德不貴無能不官無功不賞無罪不罰朝無幸位」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「朝無幸位，民無幸生」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 16,\n      \"canonicalText\": \"王者之法：等賦、政事、財萬物，所以養萬民也。田野什一，關市幾而不徵，山林澤梁，以時禁發而不稅。相地而衰政。理道之遠近而致貢。通流財物粟米，無有滯留，使相歸移也，四海之內若一家。故近者不隱其能，遠者不疾其勞，無幽閒隱僻之國，莫不趨使而安樂之。夫是之為人師。是王者之法也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-16_s-1\",\n        \"xunzi_ch-9_p-16_s-2\",\n        \"xunzi_ch-9_p-16_s-3\",\n        \"xunzi_ch-9_p-16_s-4\",\n        \"xunzi_ch-9_p-16_s-5\",\n        \"xunzi_ch-9_p-16_s-6\",\n        \"xunzi_ch-9_p-16_s-7\",\n        \"xunzi_ch-9_p-16_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王的人或事的典章法度1：等賦、政事、財萬物，所以養萬民啊。田野什一，關市幾而且不徵，山林澤梁，以時禁發而且不稅。相地而且衰政。理道的遠近而且致貢。通流財物粟米，無有滯留，使相歸移啊，四海的內若一家。所以近的人或事不隱他的能，遠的人或事不疾他的勞，無幽閒隱僻的國，莫不趨使而且安樂的。夫是的為人師。是王的人或事的典章法度啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「王者之法1：等賦、政事、財萬物，所以養萬民也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「王」、「法」、「1」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「王者之法1等賦政事財萬物所以養萬民也田野什一關市」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「田野什一，關市幾而不徵，山林澤梁，以時禁發而不稅」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 17,\n      \"canonicalText\": \"北海則有走馬吠犬焉，然而中國得而畜使之。南海則有羽翮、齒革、曾青、丹干焉，然而中國得而財之。東海則有紫紶、魚鹽焉，然而中國得而衣食之。西海則有皮革、文旄焉，然而中國得而用之。故澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而足械用，工賈不耕田而足菽粟。故虎豹為猛矣，然君子剝而用之。故天之所覆，地之所載，莫不盡其美，致其用，上以飾賢良，下以養百姓而安樂之。夫是之謂大神。《詩》曰：「天作高山，大王荒之；彼作矣，文王康之。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-17_s-1\",\n        \"xunzi_ch-9_p-17_s-2\",\n        \"xunzi_ch-9_p-17_s-3\",\n        \"xunzi_ch-9_p-17_s-4\",\n        \"xunzi_ch-9_p-17_s-5\",\n        \"xunzi_ch-9_p-17_s-6\",\n        \"xunzi_ch-9_p-17_s-7\",\n        \"xunzi_ch-9_p-17_s-8\",\n        \"xunzi_ch-9_p-17_s-9\",\n        \"xunzi_ch-9_p-17_s-10\",\n        \"xunzi_ch-9_p-17_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"北海則有走馬吠犬焉，然而且中國得而且畜使的。南海則有羽翮、齒革、曾青、丹干焉，然而且中國得而且財的。東海則有紫紶、魚鹽焉，然而且中國得而且衣食的。西海則有皮革、文旄焉，然而且中國得而且用的。所以澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而且足械用，工賈不耕田而且足菽粟。所以虎豹為猛矣，然君子剝而且用的。所以天的所覆，地的所載，莫不盡他的美，致他的用，上以飾賢良，下以養百姓而且安樂的。這就是儒家所稱的大神。《詩》說道：天作高山，大王荒的；彼作矣，文王康的。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「北海則有走馬吠犬焉，然而中國得而畜使之」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「北」、「海」、「有」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「北海則有走馬吠犬焉然而中國得而畜使之南海則有羽翮」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「南海則有羽翮、齒革、曾青、丹干焉，然而中國得而財之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 18,\n      \"canonicalText\": \"以類行雜，以一行萬。始則終，終則始，若環之無端也，舍是而天下以衰矣。天地者，生之始也；禮義者，治之始也；君子者，禮義之始也；為之，貫之，積重之，致好之者，君子之始也。故天地生君子，君子理天地；君子者，天地之參也，萬物之摠也，民之父母也。無君子，則天地不理，禮義無統，上無君師，下無父子、夫婦，是之謂至亂。君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，夫是之謂大本。故喪祭、朝聘、師旅一也；貴賤、殺生、與奪一也；君君、臣臣、父父、子子、兄兄、弟弟一也；農農、士士、工工、商商一也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-18_s-1\",\n        \"xunzi_ch-9_p-18_s-2\",\n        \"xunzi_ch-9_p-18_s-3\",\n        \"xunzi_ch-9_p-18_s-4\",\n        \"xunzi_ch-9_p-18_s-5\",\n        \"xunzi_ch-9_p-18_s-6\",\n        \"xunzi_ch-9_p-18_s-7\",\n        \"xunzi_ch-9_p-18_s-8\",\n        \"xunzi_ch-9_p-18_s-9\",\n        \"xunzi_ch-9_p-18_s-10\",\n        \"xunzi_ch-9_p-18_s-11\",\n        \"xunzi_ch-9_p-18_s-12\",\n        \"xunzi_ch-9_p-18_s-13\",\n        \"xunzi_ch-9_p-18_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"以類行雜，以一行萬。始則終，終則始，若環的無端啊，舍是而且天下以衰矣。天地的人或事，生的始啊；禮道義正道道德行修養規程道義正道的人或事，治的始啊；君子的人或事，禮道義正道道德行修養規程道義正道的始啊；為的，貫的，積重的，致好的的人或事，君子的始啊。所以天地生君子，君子理天地；君子的人或事，天地的參啊，萬物的摠啊，民的父母啊。無君子，則天地不理，禮道義正道道德行修養規程道義正道無統，上無君師，下無父子、夫婦，是的謂至亂。君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，這就是儒家所說的大本。所以喪祭、朝聘、師旅一啊；貴賤、殺生、與奪一啊；君君、臣臣、父父、子子、兄兄、弟弟一啊；農農、士士、工工、商商一啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「以類行雜，以一行萬」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「類」、「行」、「雜」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「以類行雜以一行萬始則終終則始若環之無端也舍是而天」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「始則終，終則始，若環之無端也，舍是而天下以衰矣」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 19,\n      \"canonicalText\": \"水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也。力不若牛，走不若馬，而牛馬為用，何也？曰：人能羣，彼不能羣也。人何以能羣？曰：分。分何以能行？曰：義。故義以分則和，和則一，一則多力，多力則彊，彊則勝物；故宮室可得而居也。故序四時，裁萬物，兼利天下，無它故焉，得之分義也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-19_s-1\",\n        \"xunzi_ch-9_p-19_s-2\",\n        \"xunzi_ch-9_p-19_s-3\",\n        \"xunzi_ch-9_p-19_s-4\",\n        \"xunzi_ch-9_p-19_s-5\",\n        \"xunzi_ch-9_p-19_s-6\",\n        \"xunzi_ch-9_p-19_s-7\",\n        \"xunzi_ch-9_p-19_s-8\",\n        \"xunzi_ch-9_p-19_s-9\",\n        \"xunzi_ch-9_p-19_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"水火有氣而且無生，草木有生而且無知，禽獸有知而且無正義道義，人有氣、有生、有知，亦且有正義道義，所以最為天下貴啊。力不若牛，走不若馬，而且牛馬為用，何啊？說道：人能羣，彼不能羣啊。人何以能羣？說道：分。分何以能行？說道：正義道義。所以正義道義以分則和，和則一，一則多力，多力則彊，彊則勝物；所以宮室可得而且居啊。所以序四時，裁萬物，兼利天下，無它所以焉，得的分正義道義啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「水」、「火」、「有」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「水火有氣而無生草木有生而無知禽獸有知而無義人有氣」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「力不若牛，走不若馬，而牛馬為用，何也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-20\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 20,\n      \"canonicalText\": \"故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；故宮室不可得而居也，不可少頃舍禮義之謂也。能以事親謂之孝，能以事兄謂之弟，能以事上謂之順，能以使下謂之君。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-20_s-1\",\n        \"xunzi_ch-9_p-20_s-2\",\n        \"xunzi_ch-9_p-20_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以人生不能無羣，羣而且無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；所以宮室不可得而且居啊，不可少頃舍禮正義道義道品德修養規程正義道義的謂啊。能以事親謂的孝，能以事兄謂的弟，能以事上謂的順，能以使下謂的君。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「人」、「生」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故人生不能無羣羣而無分則爭爭則亂亂則離離則弱弱則」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故宮室不可得而居也，不可少頃舍禮義之謂也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 21,\n      \"canonicalText\": \"君者，善羣也。羣道當，則萬物皆得其宜，六畜皆得其長，羣生皆得其命。故養長時，則六畜育；殺生時，則草木殖；政令時，則百姓一，賢良服。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-21_s-1\",\n        \"xunzi_ch-9_p-21_s-2\",\n        \"xunzi_ch-9_p-21_s-3\",\n        \"xunzi_ch-9_p-21_s-4\",\n        \"xunzi_ch-9_p-21_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"君的人或事，善羣啊。羣道當，則萬物皆得他的宜，六畜皆得他的長，羣生皆得他的命。所以養長時，則六畜育；殺生時，則草木殖；政令時，則百姓一，賢良服。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「君者，善羣也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「君」、「善」、「羣」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「君者善羣也羣道當則萬物皆得其宜六畜皆得其長羣生皆」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「羣道當，則萬物皆得其宜，六畜皆得其長，羣生皆得其命」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 22,\n      \"canonicalText\": \"聖主之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也。黿鼉魚鱉鰍鱣孕別之時，罔罟毒藥不入澤，不夭其生，不絕其長也。春耕、夏耘、秋收、冬藏，四者不失時，故五穀不絕，而百姓有餘食也。汙池淵沼川澤，謹其時禁，故魚鱉優多，而百姓有餘用也。斬伐養長不失其時，故山林不童，而百姓有餘材也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-22_s-1\",\n        \"xunzi_ch-9_p-22_s-2\",\n        \"xunzi_ch-9_p-22_s-3\",\n        \"xunzi_ch-9_p-22_s-4\",\n        \"xunzi_ch-9_p-22_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"聖主1的制啊：草木榮華滋碩的時，則斧斤不入山林，不夭他的生，不絕他的長啊。黿鼉魚鱉鰍鱣孕別的時，罔罟毒藥不入澤，不夭他的生，不絕他的長啊。春耕、夏耘、秋收、冬藏，四的人或事不失時，所以五穀不絕，而且百姓有餘食啊。汙池淵沼川澤，謹他的時禁，所以魚鱉優多，而且百姓有餘用啊。斬伐養長不失他的時，所以山林不童，而且百姓有餘材啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「聖主1之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「聖」、「主」、「1」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「聖主1之制也草木榮華滋碩之時則斧斤不入山林不夭其」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「黿鼉魚鱉鰍鱣孕別之時，罔罟毒藥不入澤，不夭其生，不絕其長也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-23\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 23,\n      \"canonicalText\": \"聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約。故曰：一與一是為人者，謂之聖人也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-23_s-1\",\n        \"xunzi_ch-9_p-23_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"聖王的用啊：上察於天，下錯於地，塞備天地的間，加施萬物的上，微而且明，短而且長，狹而且廣，神明博大以至約。所以說：一與一是為人的人或事，謂的聖人啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「聖」、「王」、「用」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「聖王之用也上察於天下錯於地塞備天地之間加施萬物之」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故曰：一與一是為人者，謂之聖人也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 24,\n      \"canonicalText\": \"序官：宰爵知賓客、祭祀、響食犧牲之牢數。司徒知百宗、城郭、立器之數。司馬知師旅、甲兵、乘白之數。脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師之事也。脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空之事也。相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而寡能，治田之事也。脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而財物不屈，虞師之事也。順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師之事也。論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師之事也。相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知其吉凶妖祥，傴巫跛擊之事也。脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而貨財通，治市之事也。抃急禁悍，防淫除邪，戮之以五刑，使暴悍以變，姦邪不作，司寇之事也。本政教，正法則，兼聽而時稽之，度其功勞，論其慶賞，以時慎脩，使百吏免盡，而眾庶不偷，冢宰之事也。論禮樂，正身行，廣教化，美風俗，兼覆而調一之，闢公之事也。全道德，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王之事也。故政事亂，則冢宰之罪也；國家失俗，則闢公之過也；天下不一，諸侯俗反，則天王非其人也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-24_s-1\",\n        \"xunzi_ch-9_p-24_s-2\",\n        \"xunzi_ch-9_p-24_s-3\",\n        \"xunzi_ch-9_p-24_s-4\",\n        \"xunzi_ch-9_p-24_s-5\",\n        \"xunzi_ch-9_p-24_s-6\",\n        \"xunzi_ch-9_p-24_s-7\",\n        \"xunzi_ch-9_p-24_s-8\",\n        \"xunzi_ch-9_p-24_s-9\",\n        \"xunzi_ch-9_p-24_s-10\",\n        \"xunzi_ch-9_p-24_s-11\",\n        \"xunzi_ch-9_p-24_s-12\",\n        \"xunzi_ch-9_p-24_s-13\",\n        \"xunzi_ch-9_p-24_s-14\",\n        \"xunzi_ch-9_p-24_s-15\",\n        \"xunzi_ch-9_p-24_s-16\",\n        \"xunzi_ch-9_p-24_s-17\",\n        \"xunzi_ch-9_p-24_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"序官：宰爵知賓客、祭祀、響食犧牲的牢數。司徒知百宗、城郭、立器的數。司馬知師旅、甲兵、乘白的數。脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師的事啊。脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空的事啊。相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而且寡能，治田的事啊。脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而且財物不屈，虞師的事啊。順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師的事啊。論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師的事啊。相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知他的吉凶妖祥，傴巫跛擊的事啊。脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而且貨財通，治市的事啊。抃急禁悍，防淫除邪，戮的以五刑，使暴悍以變，姦邪不作，司寇的事啊。本政教，正國家典章法度則，兼聽而且時稽的，度他的功勞，論他的慶賞，以時慎脩，使百吏免盡，而且眾庶不偷，冢宰的事啊。論禮正義道義道品德修養規程樂，正身行，廣教化，美風俗，兼覆而且調一的，闢公的事啊。全道品德修養，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王的事啊。所以政事亂，則冢宰的罪啊；國家失俗，則闢公的過啊；天下不一，諸侯俗反，則天王絕不是他的人啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「序官：宰爵知賓客、祭祀、響食犧牲之牢數」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「序」、「官」、「宰」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「序官宰爵知賓客祭祀響食犧牲之牢數司徒知百宗城郭立」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「司徒知百宗、城郭、立器之數」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 25,\n      \"canonicalText\": \"具具而王，具具而霸，具具而存，具具而亡。用萬乘之國者，威彊之所以立也，名聲之所以美也，敵人之所以屈也，國之所以安危臧否也，制與在此，亡乎人。王、霸、安存、危殆、滅亡，制與在我，亡乎人。夫威彊未足以殆鄰敵也，名聲未足以縣天下也，則是國未能獨立也，豈渠得免夫累乎？天下脅於暴國，而黨為吾所不欲於是者，日與桀同事同行，無害為堯。是非功名之所就也，非存亡安危之所墮也。功名之所就，存亡安危之所墮，必將於愉殷赤心之所。誠以其國為王者之所亦王，以其國為危殆滅亡之所亦危殆滅亡。殷之日，案以中立，無有所偏，而為縱橫之事，偃然案兵無動，以觀夫暴國之相卒也。案平政教，審節奏，砥礪百姓，為是之日，而兵剸天下勁矣。案然修仁義，伉隆高，正法則，選賢良，養百姓，為是之日，而名聲剸天下之美矣。權者重之，兵者勁之，名聲者美之。夫堯舜者一天下也，不能加毫末於是矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-25_s-1\",\n        \"xunzi_ch-9_p-25_s-2\",\n        \"xunzi_ch-9_p-25_s-3\",\n        \"xunzi_ch-9_p-25_s-4\",\n        \"xunzi_ch-9_p-25_s-5\",\n        \"xunzi_ch-9_p-25_s-6\",\n        \"xunzi_ch-9_p-25_s-7\",\n        \"xunzi_ch-9_p-25_s-8\",\n        \"xunzi_ch-9_p-25_s-9\",\n        \"xunzi_ch-9_p-25_s-10\",\n        \"xunzi_ch-9_p-25_s-11\",\n        \"xunzi_ch-9_p-25_s-12\",\n        \"xunzi_ch-9_p-25_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"具具而且王，具具而且霸，具具而且存，具具而且亡。用萬乘的國的人或事，威彊的所以立啊，名聲的所以美啊，敵人的所以屈啊，國的所以安危臧否啊，制與在此，亡乎人。王、霸、安存、危殆、滅亡，制與在我，亡乎人。夫威彊未足以殆鄰敵啊，名聲未足以縣天下啊，則是國未能獨立啊，豈渠得免夫累乎？天下脅於暴國，而且黨為吾所不欲於是的人或事，日與桀同事同行，無害為堯。是絕不是功名的所就啊，絕不是存亡安危的所墮啊。功名的所就，存亡安危的所墮，必將於愉殷赤心的所。誠以他的國為王的人或事的所亦王，以他的國為危殆滅亡的所亦危殆滅亡。殷的日，案以中立，無有所偏，而且為縱橫的事，偃然案兵無動，以觀夫暴國的相卒啊。案平政教，審節奏，砥礪百姓，為是的日，而且兵剸天下勁矣。案然修仁愛之德道義正道，伉隆高，正典章法度則，選賢良，養百姓，為是的日，而且名聲剸天下的美矣。權的人或事重的，兵的人或事勁的，名聲的人或事美的。夫堯舜的人或事一天下啊，不能加毫末於是矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「具具而王，具具而霸，具具而存，具具而亡」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「具」、「具」、「王」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「具具而王具具而霸具具而存具具而亡用萬乘之國者威彊」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「用萬乘之國者，威彊之所以立也，名聲之所以美也，敵人之所以屈也，國之所以安危臧否也，制與在此，亡乎人」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"order\": 26,\n      \"canonicalText\": \"權謀傾覆之人退，則賢良知聖之士案自進矣。刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。務本事，積財物，而勿忘棲遲薛越也，是使群臣百姓皆以制度行，則財物積，國家案自富矣。三者體此而天下服，暴國之君案自不能用其兵矣。何則？彼無與至也。彼其所與至者，必其民也。其民之親我也，歡若父母，好我芳如芝蘭，反顧其上則若灼黥，若仇讎；彼人之情性也雖桀蹠，豈有肯為其所惡，賊其所好者哉！彼以奪矣。故古之人，有以一國取天下者，非往行之也，脩政其所，莫不願，如是而可以誅暴禁悍矣。故周公南征而北國怨，曰：「何獨不來也！」東征而西國怨，曰：「何獨後我也！」孰能有與是鬥者與？安以其國為是者王。殷之日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎之士，然後漸賞慶以先之，嚴刑罰以防之，擇士之知事者，使相率貫也，是以厭然畜積修飾，而物用之足也。兵革器械者，彼將日日暴露毀折之中原；我將脩飾之，拊循之，掩蓋之於府庫。貨財粟米者，彼將日日棲遲薛越之中野，我今將畜積並聚之於倉廩。材技股肱健勇爪牙之士，彼將日日挫頓竭之於仇敵，我今將來致之，並閱之，砥礪之於朝廷。如是，則彼日積敝，我日積完；彼日積貧，我日積富；彼日積勞，我日積佚。君臣上下之間者，彼將厲厲焉日日相離疾也，我將頓頓焉日日相親愛也，以是待其敝。安以其國為是者霸。立身則從傭俗，事行則遵傭故，進退貴賤則舉傭士，之所以接下之人百姓者則庸寬惠，如是者則安存。立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，之所以接下之人百姓者則好取侵奪，如是者危殆。立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐故，之所以接下之人百姓者，則好用其死力矣，而慢其功勞，好用其籍斂矣，而忘其本務，如是者滅亡。此五等者，不可不善擇也，王、霸、安存、危殆、滅亡之具也。善擇者制人，不善擇者人制之。善擇之者王，不善擇之者亡。夫王者之與亡者，制人之與人制之也，是其為相縣也亦遠矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-9_p-26_s-1\",\n        \"xunzi_ch-9_p-26_s-2\",\n        \"xunzi_ch-9_p-26_s-3\",\n        \"xunzi_ch-9_p-26_s-4\",\n        \"xunzi_ch-9_p-26_s-5\",\n        \"xunzi_ch-9_p-26_s-6\",\n        \"xunzi_ch-9_p-26_s-7\",\n        \"xunzi_ch-9_p-26_s-8\",\n        \"xunzi_ch-9_p-26_s-9\",\n        \"xunzi_ch-9_p-26_s-10\",\n        \"xunzi_ch-9_p-26_s-11\",\n        \"xunzi_ch-9_p-26_s-12\",\n        \"xunzi_ch-9_p-26_s-13\",\n        \"xunzi_ch-9_p-26_s-14\",\n        \"xunzi_ch-9_p-26_s-15\",\n        \"xunzi_ch-9_p-26_s-16\",\n        \"xunzi_ch-9_p-26_s-17\",\n        \"xunzi_ch-9_p-26_s-18\",\n        \"xunzi_ch-9_p-26_s-19\",\n        \"xunzi_ch-9_p-26_s-20\",\n        \"xunzi_ch-9_p-26_s-21\",\n        \"xunzi_ch-9_p-26_s-22\",\n        \"xunzi_ch-9_p-26_s-23\",\n        \"xunzi_ch-9_p-26_s-24\",\n        \"xunzi_ch-9_p-26_s-25\",\n        \"xunzi_ch-9_p-26_s-26\",\n        \"xunzi_ch-9_p-26_s-27\",\n        \"xunzi_ch-9_p-26_s-28\",\n        \"xunzi_ch-9_p-26_s-29\",\n        \"xunzi_ch-9_p-26_s-30\",\n        \"xunzi_ch-9_p-26_s-31\",\n        \"xunzi_ch-9_p-26_s-32\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"權謀傾覆的人退，則賢良知聖的士案自進矣。刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。務本事，積財物，而且勿忘棲遲薛越啊，是使群臣百姓皆以制度行，則財物積，國家案自富矣。三的人或事體此而且天下服，暴國的君案自不能用他的兵矣。何則？彼無與至啊。彼他的所與至的人或事，必他的民啊。他的民的親我啊，歡若父母，好我芳如芝蘭，反顧他的上則若灼黥，若仇讎；彼人的情性啊雖桀蹠，豈有肯為他的所惡，賊他的所好的人或事哉！彼以奪矣。所以古的人，有以一國取天下的人或事，絕不是往行的啊，脩政他的所，莫不願，如是而且可以誅暴禁悍矣。所以周公南征而且北國怨，說道：何獨不來啊！東征而且西國怨，說道：何獨後我啊！孰能有與是鬥的人或事與？安以他的國為是的人或事王。殷的日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎的士，然後漸賞慶以先的，嚴刑罰以防的，擇士的知事的人或事，使相率貫啊，是以厭然畜積修飾，而且物用的足啊。兵革器械的人或事，彼將日日暴露毀折的中原；我將脩飾的，拊循的，掩蓋的於府庫。貨財粟米的人或事，彼將日日棲遲薛越的中野，我今將畜積並聚的於倉廩。材技股肱健勇爪牙的士，彼將日日挫頓竭的於仇敵，我今將來致的，並閱的，砥礪的於朝廷。如是，則彼日積敝，我日積完；彼日積貧，我日積富；彼日積勞，我日積佚。君臣上下的間的人或事，彼將厲厲焉日日相離疾啊，我將頓頓焉日日相親愛啊，以是待他的敝。安以他的國為是的人或事霸。立身則從傭俗，事行則遵傭所以，進退貴賤則舉傭士，的所以接下的人百姓的人或事則庸寬惠，如是的人或事則安存。立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，的所以接下的人百姓的人或事則好取侵奪，如是的人或事危殆。立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐所以，的所以接下的人百姓的人或事，則好用他的死力矣，而且慢他的功勞，好用他的籍斂矣，而且忘他的本務，如是的人或事滅亡。此五等的人或事，不可不善擇啊，王、霸、安存、危殆、滅亡的具啊。善擇的人或事制人，不善擇的人或事人制的。善擇的的人或事王，不善擇的的人或事亡。夫王的人或事的與亡的人或事，制人的與人制的啊，是他的為相縣啊亦遠矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王制〉。荀子立足於戰國後期的政治實踐，開篇「權謀傾覆之人退，則賢良知聖之士案自進矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「權」、「謀」、「傾」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「權謀傾覆之人退則賢良知聖之士案自進矣刑政平百姓和」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"請問為政？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"曰：賢能不待次而舉，罷不能不待須而廢，元惡不待教而誅，中庸雜民不待政而化。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"分未定也，則有昭繆也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"雖王公士大夫之子孫也，不能屬於禮義，則歸之庶人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"雖庶人之子孫也，積文學，正身行，能屬於禮義，則歸之卿相士大夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"故姦言，姦說，姦事，姦能，遁逃反側之民，職而教之，須而待之，勉之以慶賞，懲之以刑罰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"安職則畜，不安職則棄。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"五疾，上收而養之，材而事之，官施而衣食之，兼覆無遺。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"纔行反時者死無赦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-1_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"夫是之謂天德，是王者之政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-2_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"聽政之大分：以善至者待之以禮，以不善至者待之以刑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-2_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"兩者分別，則賢不肖不雜，是非不亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-2_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"賢不肖不雜，則英傑至，是非不亂，則國家治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-2_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"若是，名聲日聞，天下願，令行禁止，王者之事畢矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"凡聽：威嚴猛厲，而不好假道人，則下畏恐而不親，周閉而不竭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"若是，則大事殆乎弛，小事殆乎遂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"和解調通，好假道人，而無所凝止之，則姦言並至，嘗試之說鋒起。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"若是，則聽大事煩，是又傷之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"故法而不議，則法之所不至者必廢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"職而不通，則職之所不及者必隊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"故法而議，職而通，無隱謀，無遺善，而百事無過，非君子莫能。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"故公平者，聽之衡也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"中和者，聽之繩也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"其有法者以法行，無法者以類舉，聽之盡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"偏黨而不經，聽之闢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 12,\n      \"canonicalText\": \"故有良法而亂者，有之矣，有君子而亂者，自古及今，未嘗聞也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 13,\n      \"canonicalText\": \"傳曰：「治生乎君子，亂生乎小人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-3_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-3\",\n      \"order\": 14,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"分均則不偏，埶齊則不壹，眾齊則不使。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"有天有地，而上下有差；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"明王始立，而處國有制。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"夫兩貴之不能相事，兩賤之不能相使，是天數也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"埶位齊，而欲惡同，物不能澹則必爭；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"爭則必亂，亂則窮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"先王惡其亂也，故制禮義以分之，使有貧富貴賤之等，足以相兼臨者，是養天下之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"《書》曰：「維齊非齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-4_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"馬駭輿，則君子不安輿；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"庶人駭政，則君子不安位。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"馬駭輿，則莫若靜之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"庶人駭政，則莫若惠之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"選賢良，舉篤敬，興孝弟，收孤寡，補貧窮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"如是，則庶人安政矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"庶人安政，然後君子安位。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"傳曰：「君者、舟也，庶人者、水也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"水則載舟，水則覆舟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"故君人者，欲安、則莫若平政愛民矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"欲榮、則莫若隆禮敬士矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"欲立功名、則莫若尚賢使能矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"－是人君之大節也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"三節者當，則其餘莫不當矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"三節者不當，則其餘雖曲當，猶將無益也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"孔子曰：「大節是也，小節是也，上君也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"大節是也，小節一齣焉，一入焉，中君也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 19,\n      \"canonicalText\": \"大節非也，小節雖是也，吾無觀其餘矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-5_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-5\",\n      \"order\": 20,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"成侯、嗣公聚斂計數之君也，未及取民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"子產取民者也，未及為政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"管仲為政者也，未及修禮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"故修禮者王，為政者彊，取民者安，聚斂者亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"故王者富民，霸者富士，僅存之國富大夫，亡國富筐篋，實府庫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"筐篋已富，府庫已實，而百姓貧：夫是之謂上溢而下漏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"入不可以守，出不可以戰，則傾覆滅亡可立而待也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"故我聚之以亡，敵得之以彊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-6_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"聚斂者，召寇、肥敵、亡國、危身之道也，故明君不蹈也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-7_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"王奪之人，霸奪之與，彊奪之地。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-7_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"奪之人者臣諸侯，奪之與者友諸侯，奪之地者敵諸侯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-7_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"臣諸侯者王，友諸侯者霸，敵諸侯者危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"用彊者：人之城守，人之出戰，而我以力勝之也，則傷人之民必甚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"傷人之民甚，則人之民必惡我甚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"人之民惡我甚，則日欲與我鬥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"人之城守，人之出戰，而我以力勝之，則傷吾民必甚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"傷吾民甚，則吾民之惡我必甚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"吾民之惡我甚，則日不欲為我鬥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"人之民日欲與我鬥，吾民日不欲為我鬥，是彊者之所以反弱也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"地來而民去，累多而功少，雖守者益，所以守者損，是以大者之所以反削也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-8_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"諸侯莫不懷交接怨，而不忘其敵，伺彊大之間，承彊大之敝，此彊大之殆時也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-9_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"知彊大者不務彊也，慮以王命，全其力，凝其德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-9_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"力全則諸侯不能弱也，德凝則諸侯不能削也，天下無王霸主，則常勝矣：是知彊道者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"彼霸者則不然：闢田野，實倉廩，便備用，案謹募選閱材伎之士，然後漸慶賞以先之，嚴刑罰以糾之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"存亡繼絕，衛弱禁暴，而無兼併之心，則諸侯親之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"修友敵之道，以敬接諸侯，則諸侯說之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"所以親之者，以不併也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"並之見，則諸侯疏矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"所以說之者，以友敵也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"臣之見，則諸侯離矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"故明其不併之行，信其友敵之道，天下無王霸主，則常勝矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-10_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"是知霸道者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-11_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"閔王毀於五國，桓公劫於魯莊，無它故焉，非其道而慮之以王也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"彼王者不然：仁眇天下，義眇天下，威眇天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"仁眇天下，故天下莫不親也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"義眇天下，故天下莫不貴也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"威眇天下，故天下莫敢敵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"以不敵之威，輔服人之道，故不戰而勝，不攻而得，甲兵不勞而天下服，是知王道者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-12_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"知此三具者，欲王而王，欲霸而霸，欲彊而彊矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-13_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"王者之人：飾動以禮義，聽斷以類，明振毫末，舉措應變而不窮，夫是之謂有原。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-13_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"是王者之人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-14_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"王者之制：道不過三代，法不二後王；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-14_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"道過三代謂之蕩，法二後王謂之不雅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-14_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-14_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"聲、則非雅聲者舉廢，色、則凡非舊文者舉息，械用，則凡非舊器者舉毀，夫是之謂復古，是王者之制也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"王者之論：無德不貴，無能不官，無功不賞，無罪不罰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"朝無幸位，民無幸生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"尚賢使能，而等位不遺；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"析願禁悍，而刑罰不過。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"百姓曉然皆知夫為善於家，而取賞於朝也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"為不善於幽，而蒙刑於顯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 7,\n      \"canonicalText\": \"夫是之謂定論。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-15_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-15\",\n      \"order\": 8,\n      \"canonicalText\": \"是王者之論也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"王者之法：等賦、政事、財萬物，所以養萬民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"田野什一，關市幾而不徵，山林澤梁，以時禁發而不稅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"相地而衰政。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"理道之遠近而致貢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"通流財物粟米，無有滯留，使相歸移也，四海之內若一家。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"故近者不隱其能，遠者不疾其勞，無幽閒隱僻之國，莫不趨使而安樂之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"夫是之為人師。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-16_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"是王者之法也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"北海則有走馬吠犬焉，然而中國得而畜使之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"南海則有羽翮、齒革、曾青、丹干焉，然而中國得而財之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"東海則有紫紶、魚鹽焉，然而中國得而衣食之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"西海則有皮革、文旄焉，然而中國得而用之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"故澤人足乎木，山人足乎魚，農夫不斲削、不陶冶而足械用，工賈不耕田而足菽粟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"故虎豹為猛矣，然君子剝而用之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"故天之所覆，地之所載，莫不盡其美，致其用，上以飾賢良，下以養百姓而安樂之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 8,\n      \"canonicalText\": \"夫是之謂大神。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 9,\n      \"canonicalText\": \"《詩》曰：「天作高山，大王荒之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 10,\n      \"canonicalText\": \"彼作矣，文王康之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-17_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-17\",\n      \"order\": 11,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"以類行雜，以一行萬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"始則終，終則始，若環之無端也，舍是而天下以衰矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"天地者，生之始也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"禮義者，治之始也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"君子者，禮義之始也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"為之，貫之，積重之，致好之者，君子之始也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"故天地生君子，君子理天地；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"君子者，天地之參也，萬物之摠也，民之父母也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"無君子，則天地不理，禮義無統，上無君師，下無父子、夫婦，是之謂至亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"君臣、父子、兄弟、夫婦，始則終，終則始，與天地同理，與萬世同久，夫是之謂大本。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 11,\n      \"canonicalText\": \"故喪祭、朝聘、師旅一也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 12,\n      \"canonicalText\": \"貴賤、殺生、與奪一也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 13,\n      \"canonicalText\": \"君君、臣臣、父父、子子、兄兄、弟弟一也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-18_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-18\",\n      \"order\": 14,\n      \"canonicalText\": \"農農、士士、工工、商商一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"水火有氣而無生，草木有生而無知，禽獸有知而無義，人有氣、有生、有知，亦且有義，故最為天下貴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"力不若牛，走不若馬，而牛馬為用，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"曰：人能羣，彼不能羣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"人何以能羣？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"曰：分。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"分何以能行？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 7,\n      \"canonicalText\": \"曰：義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 8,\n      \"canonicalText\": \"故義以分則和，和則一，一則多力，多力則彊，彊則勝物；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 9,\n      \"canonicalText\": \"故宮室可得而居也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-19_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-19\",\n      \"order\": 10,\n      \"canonicalText\": \"故序四時，裁萬物，兼利天下，無它故焉，得之分義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-20_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"故人生不能無羣，羣而無分則爭，爭則亂，亂則離，離則弱，弱則不能勝物；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-20_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"故宮室不可得而居也，不可少頃舍禮義之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-20_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"能以事親謂之孝，能以事兄謂之弟，能以事上謂之順，能以使下謂之君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"君者，善羣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"羣道當，則萬物皆得其宜，六畜皆得其長，羣生皆得其命。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"故養長時，則六畜育；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"殺生時，則草木殖；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-21_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"政令時，則百姓一，賢良服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"聖主之制也：草木榮華滋碩之時，則斧斤不入山林，不夭其生，不絕其長也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"黿鼉魚鱉鰍鱣孕別之時，罔罟毒藥不入澤，不夭其生，不絕其長也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"春耕、夏耘、秋收、冬藏，四者不失時，故五穀不絕，而百姓有餘食也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-22\",\n      \"order\": 4,\n      \"canonicalText\": \"汙池淵沼川澤，謹其時禁，故魚鱉優多，而百姓有餘用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-22_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-22\",\n      \"order\": 5,\n      \"canonicalText\": \"斬伐養長不失其時，故山林不童，而百姓有餘材也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-23_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"聖王之用也：上察於天，下錯於地，塞備天地之間，加施萬物之上，微而明，短而長，狹而廣，神明博大以至約。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-23_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"故曰：一與一是為人者，謂之聖人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"序官：宰爵知賓客、祭祀、響食犧牲之牢數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"司徒知百宗、城郭、立器之數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 3,\n      \"canonicalText\": \"司馬知師旅、甲兵、乘白之數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 4,\n      \"canonicalText\": \"脩憲命，審詩商，禁淫聲，以時順脩，使夷俗邪音不敢亂雅，大師之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 5,\n      \"canonicalText\": \"脩隄梁，通溝澮，行水潦，安水臧，以時決塞，歲雖兇敗水旱，使民有所耘艾，司空之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 6,\n      \"canonicalText\": \"相高下，視肥墝，序五種，省農功，謹蓄藏，以時順脩，使農夫樸力而寡能，治田之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 7,\n      \"canonicalText\": \"脩火憲，養山林藪澤草木、魚鱉、百素，以時禁發，使國家足用，而財物不屈，虞師之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 8,\n      \"canonicalText\": \"順州里，定廛宅，養六畜，閒樹藝，勸教化，趨孝弟，以時順修，使百姓順命，安樂處鄉，鄉師之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 9,\n      \"canonicalText\": \"論百工，審時事，辨功苦，尚完利，便備用，使雕琢文采不敢專造於家，工師之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 10,\n      \"canonicalText\": \"相陰陽，佔祲兆，鑽龜陳卦，主攘擇五卜，知其吉凶妖祥，傴巫跛擊之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 11,\n      \"canonicalText\": \"脩採清，易道路，謹盜賊，平室律，以時順修，使賓旅安而貨財通，治市之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 12,\n      \"canonicalText\": \"抃急禁悍，防淫除邪，戮之以五刑，使暴悍以變，姦邪不作，司寇之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 13,\n      \"canonicalText\": \"本政教，正法則，兼聽而時稽之，度其功勞，論其慶賞，以時慎脩，使百吏免盡，而眾庶不偷，冢宰之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 14,\n      \"canonicalText\": \"論禮樂，正身行，廣教化，美風俗，兼覆而調一之，闢公之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 15,\n      \"canonicalText\": \"全道德，致隆高，綦文理，一天下，振毫末，使天下莫不順比從服，天王之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 16,\n      \"canonicalText\": \"故政事亂，則冢宰之罪也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 17,\n      \"canonicalText\": \"國家失俗，則闢公之過也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-24_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-24\",\n      \"order\": 18,\n      \"canonicalText\": \"天下不一，諸侯俗反，則天王非其人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 1,\n      \"canonicalText\": \"具具而王，具具而霸，具具而存，具具而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 2,\n      \"canonicalText\": \"用萬乘之國者，威彊之所以立也，名聲之所以美也，敵人之所以屈也，國之所以安危臧否也，制與在此，亡乎人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 3,\n      \"canonicalText\": \"王、霸、安存、危殆、滅亡，制與在我，亡乎人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 4,\n      \"canonicalText\": \"夫威彊未足以殆鄰敵也，名聲未足以縣天下也，則是國未能獨立也，豈渠得免夫累乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 5,\n      \"canonicalText\": \"天下脅於暴國，而黨為吾所不欲於是者，日與桀同事同行，無害為堯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 6,\n      \"canonicalText\": \"是非功名之所就也，非存亡安危之所墮也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 7,\n      \"canonicalText\": \"功名之所就，存亡安危之所墮，必將於愉殷赤心之所。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 8,\n      \"canonicalText\": \"誠以其國為王者之所亦王，以其國為危殆滅亡之所亦危殆滅亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 9,\n      \"canonicalText\": \"殷之日，案以中立，無有所偏，而為縱橫之事，偃然案兵無動，以觀夫暴國之相卒也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 10,\n      \"canonicalText\": \"案平政教，審節奏，砥礪百姓，為是之日，而兵剸天下勁矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 11,\n      \"canonicalText\": \"案然修仁義，伉隆高，正法則，選賢良，養百姓，為是之日，而名聲剸天下之美矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 12,\n      \"canonicalText\": \"權者重之，兵者勁之，名聲者美之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-25_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-25\",\n      \"order\": 13,\n      \"canonicalText\": \"夫堯舜者一天下也，不能加毫末於是矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 1,\n      \"canonicalText\": \"權謀傾覆之人退，則賢良知聖之士案自進矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 2,\n      \"canonicalText\": \"刑政平，百姓和，國俗節，則兵勁城固，敵國案自詘矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 3,\n      \"canonicalText\": \"務本事，積財物，而勿忘棲遲薛越也，是使群臣百姓皆以制度行，則財物積，國家案自富矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 4,\n      \"canonicalText\": \"三者體此而天下服，暴國之君案自不能用其兵矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 5,\n      \"canonicalText\": \"何則？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 6,\n      \"canonicalText\": \"彼無與至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 7,\n      \"canonicalText\": \"彼其所與至者，必其民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 8,\n      \"canonicalText\": \"其民之親我也，歡若父母，好我芳如芝蘭，反顧其上則若灼黥，若仇讎；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 9,\n      \"canonicalText\": \"彼人之情性也雖桀蹠，豈有肯為其所惡，賊其所好者哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 10,\n      \"canonicalText\": \"彼以奪矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 11,\n      \"canonicalText\": \"故古之人，有以一國取天下者，非往行之也，脩政其所，莫不願，如是而可以誅暴禁悍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 12,\n      \"canonicalText\": \"故周公南征而北國怨，曰：「何獨不來也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 13,\n      \"canonicalText\": \"」東征而西國怨，曰：「何獨後我也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 14,\n      \"canonicalText\": \"」孰能有與是鬥者與？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 15,\n      \"canonicalText\": \"安以其國為是者王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 16,\n      \"canonicalText\": \"殷之日，安以靜兵息民，慈愛百姓，闢田野，實倉廩，便備用，安謹募選閱材伎之士，然後漸賞慶以先之，嚴刑罰以防之，擇士之知事者，使相率貫也，是以厭然畜積修飾，而物用之足也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 17,\n      \"canonicalText\": \"兵革器械者，彼將日日暴露毀折之中原；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 18,\n      \"canonicalText\": \"我將脩飾之，拊循之，掩蓋之於府庫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 19,\n      \"canonicalText\": \"貨財粟米者，彼將日日棲遲薛越之中野，我今將畜積並聚之於倉廩。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 20,\n      \"canonicalText\": \"材技股肱健勇爪牙之士，彼將日日挫頓竭之於仇敵，我今將來致之，並閱之，砥礪之於朝廷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 21,\n      \"canonicalText\": \"如是，則彼日積敝，我日積完；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 22,\n      \"canonicalText\": \"彼日積貧，我日積富；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-23\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 23,\n      \"canonicalText\": \"彼日積勞，我日積佚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-24\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 24,\n      \"canonicalText\": \"君臣上下之間者，彼將厲厲焉日日相離疾也，我將頓頓焉日日相親愛也，以是待其敝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-25\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 25,\n      \"canonicalText\": \"安以其國為是者霸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-26\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 26,\n      \"canonicalText\": \"立身則從傭俗，事行則遵傭故，進退貴賤則舉傭士，之所以接下之人百姓者則庸寬惠，如是者則安存。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-27\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 27,\n      \"canonicalText\": \"立身則輕楛，事行則蠲疑，進退貴賤則舉佞侻，之所以接下之人百姓者則好取侵奪，如是者危殆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-28\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 28,\n      \"canonicalText\": \"立身則憍暴，事行則傾覆，進退貴賤則舉幽險詐故，之所以接下之人百姓者，則好用其死力矣，而慢其功勞，好用其籍斂矣，而忘其本務，如是者滅亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-29\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 29,\n      \"canonicalText\": \"此五等者，不可不善擇也，王、霸、安存、危殆、滅亡之具也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-30\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 30,\n      \"canonicalText\": \"善擇者制人，不善擇者人制之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-31\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 31,\n      \"canonicalText\": \"善擇之者王，不善擇之者亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-9_p-26_s-32\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-9\",\n      \"passageId\": \"xunzi_ch-9_p-26\",\n      \"order\": 32,\n      \"canonicalText\": \"夫王者之與亡者，制人之與人制之也，是其為相縣也亦遠矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
